import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 29 Funny or not?","description":"学习 whether 从句与选择范围，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 29 Funny or not?","description":"学习 whether 从句与选择范围，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 whether 从句与选择范围，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 28 Five pounds too dear","link":"/life/english/new-concept/book-3/unit-02/lesson-028"},"next":{"text":"第三册：培养技能 · Lesson 30 The death of a ghost","link":"/life/english/new-concept/book-3/unit-02/lesson-030"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 28 Five pounds too dear","link":"/life/english/new-concept/book-3/unit-02/lesson-028"},"next":{"text":"第三册：培养技能 · Lesson 30 The death of a ghost","link":"/life/english/new-concept/book-3/unit-02/lesson-030"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-029.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-029.md"}'),r={name:"life/english/new-concept/book-3/unit-02/lesson-029.md"};function i(l,e,s,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-29-funny-or-not" tabindex="-1">第三册：培养技能 · Lesson 29 Funny or not? <a class="header-anchor" href="#第三册-培养技能-·-lesson-29-funny-or-not" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 29 Funny or not?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从幽默效果因人而异讨论进入话语转折。一个玩笑是否奏效与听者的背景和场合有关，解释时应给出情境而非单纯评判听者。学习 whether 引导两种可能或未知结论，并练习把“是否”问题写成陈述语序，形成清晰的评论句。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>humour</td><td>/ˈhjuːmə/</td><td>n.</td><td>幽默</td><td>a sense of humour</td></tr><tr><td>audience</td><td>/ˈɔːdiəns/</td><td>n.</td><td>观众</td><td>a puzzled audience</td></tr><tr><td>reaction</td><td>/riˈækʃən/</td><td>n.</td><td>反应</td><td>an unexpected reaction</td></tr><tr><td>context</td><td>/ˈkɒntekst/</td><td>n.</td><td>语境</td><td>understand the context</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take something seriously — 认真对待某事</li><li>at someone&#39;s expense — 以让某人难堪为代价</li></ul><h2 id="语法讲解-whether-从句与选择范围" tabindex="-1">语法讲解：whether 从句与选择范围 <a class="header-anchor" href="#语法讲解-whether-从句与选择范围" aria-label="Permalink to &quot;语法讲解：whether 从句与选择范围&quot;">​</a></h2><p>whether 引导间接疑问，表示两种或多种可能中的选择，后面用陈述语序。whether or not 表示无论是否时，可引导让步状语从句；表达“还不知道是否”时则是宾语或主语等名词性从句。介词之后、to do 之前及明确搭配 or not 时通常优先使用 whether，而不是任意换成 if。判断从句功能要看它在整句中承担什么角色，不能只把 whether 统一译成一个中文词而忽略逻辑关系。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Whether the joke works depends partly on what the audience already knows.</p></blockquote><p>这个笑话是否有效，部分取决于观众已经知道什么。</p><p>whether 从句整体作主语，谓语为单数 depends；what 从句作 on 的宾语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Whether does the joke work depends ... 错在从句倒装；应保持 the joke works 的陈述语序。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 confused rather than amused 时对比两个过去分词的重音；再用自己的话复述 whether 从句，检查语序。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The joke relied on an unfamiliar local saying. Several guests looked confused rather than amused. A short explanation would have helped them understand the reference.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句评价一次玩笑失败的原因，提出更合适的表达。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>把原因定位于共享背景不足，避免直接评价听者的能力。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>例句中的整句谓语是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> depends</p><p><strong>解析：</strong> whether 从句整体是主语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：We argued about ___ to include the joke.（whether/if）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whether</p><p><strong>解析：</strong> 介词后且接不定式时使用 whether。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>partly 能否省略而完全不改变意思？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 省略会去掉“只是部分原因”的限定。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：whether 从句与选择范围。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-028">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-030">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(r,[["render",i]]);export{p as __pageData,k as default};
